const items = $input.all();
const form = $('Envio de Relatório ERP').first().json;

// =====================================================
// CONFIGURAÇÕES / FUNÇÕES
// =====================================================

const meses = {
  JANEIRO: 1,
  FEVEREIRO: 2,
  MARÇO: 3,
  ABRIL: 4,
  MAIO: 5,
  JUNHO: 6,
  JULHO: 7,
  AGOSTO: 8,
  SETEMBRO: 9,
  OUTUBRO: 10,
  NOVEMBRO: 11,
  DEZEMBRO: 12
};

function numero(valor) {
  if (typeof valor === 'number') return valor;

  if (valor === null || valor === undefined || valor === '') {
    return 0;
  }

  let texto = String(valor).trim();

  // Brasileiro: 669.859,0000
  if (texto.includes(',')) {
    texto = texto
      .replace(/\./g, '')
      .replace(',', '.');
  }

  const n = Number(texto);

  return Number.isFinite(n) ? n : 0;
}

function limparDescricao(valor) {
  return String(valor || '')
    .replace(/^\s*-\s*/, '')
    .trim();
}

function normalizarData(valor) {

  if (valor === null || valor === undefined) {
    return null;
  }

  // Excel serial date
  if (typeof valor === 'number' && valor > 20000) {

    const excelEpoch = new Date(Date.UTC(1899, 11, 30));
    const data = new Date(
      excelEpoch.getTime() +
      valor * 86400000
    );

    const ano = data.getUTCFullYear();
    const mes = data.getUTCMonth() + 1;
    const dia = data.getUTCDate();

    return {
      iso:
        `${ano}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`,
      dia,
      mes,
      ano
    };
  }

  const texto = String(valor).trim();

  // 2026-08-03...
  let match = texto.match(
    /^(\d{4})-(\d{2})-(\d{2})/
  );

  if (match) {

    const ano = Number(match[1]);
    const mes = Number(match[2]);
    const dia = Number(match[3]);

    return {
      iso: `${match[1]}-${match[2]}-${match[3]}`,
      dia,
      mes,
      ano
    };
  }

  // 03/08/2026
  match = texto.match(
    /^(\d{2})\/(\d{2})\/(\d{4})/
  );

  if (match) {

    const dia = Number(match[1]);
    const mes = Number(match[2]);
    const ano = Number(match[3]);

    return {
      iso:
        `${ano}-${String(mes).padStart(2, '0')}-${String(dia).padStart(2, '0')}`,
      dia,
      mes,
      ano
    };
  }

  return null;
}

function valoresLinha(json) {

  return Object.values(json || {})
    .filter(valor =>
      valor !== null &&
      valor !== undefined &&
      String(valor).trim() !== ''
    );
}

// =====================================================
// DADOS DO FORM
// =====================================================

const mesFormularioTexto =
  String(form.MES || '')
    .trim()
    .toUpperCase();

const mesFormulario =
  meses[mesFormularioTexto];

const anoFormularioTexto =
  String(form.ANO || '').trim();

const anoFormulario =
  Number(anoFormularioTexto);

// =====================================================
// LINHAS EXTRAÍDAS DO XLS
// =====================================================

const linhas = items
  .map(item => valoresLinha(item.json))
  .filter(valores => valores.length > 0);

// =====================================================
// IDENTIFICA O RELATÓRIO
// =====================================================

const ehRelatorioProducao =
  linhas.some(valores => {

    const texto =
      valores.join(' ').toUpperCase();

    return (
      texto.includes(
        'RELATÓRIO DE ENTRADA DE PRODUÇÃO'
      ) ||
      texto.includes(
        'RELATORIO DE ENTRADA DE PRODUCAO'
      )
    );
  });

// =====================================================
// PARSER
// =====================================================

const ordens = [];

let produtoAtual = null;
let ordemAtual = null;

for (
  let indice = 0;
  indice < linhas.length;
  indice++
) {

  const valores = linhas[indice];

  const primeiro = valores[0];
  const segundo = valores[1];

  // ---------------------------------------------------
  // CABEÇALHO DO PRODUTO
  //
  // 1001 - PRODUCT A...
  // ---------------------------------------------------

  if (
    valores.length <= 2 &&
    primeiro !== undefined &&
    segundo !== undefined &&
    /^\d+$/.test(String(primeiro).replace('.0', '')) &&
    String(segundo).trim().startsWith('-')
  ) {

    const codigo =
      Number(primeiro);

    if (codigo !== 1) {

      produtoAtual = {
        codigoProduto: codigo,
        produto:
          limparDescricao(segundo)
      };

      continue;
    }
  }

  // ---------------------------------------------------
  // ORDEM DE PRODUÇÃO
  //
  // 1 - PRODUÇÃO DOC DATA QTD UN VLR VLR TOTAL
  // ---------------------------------------------------

  if (
    primeiro !== undefined &&
    Number(primeiro) === 1 &&
    segundo !== undefined &&
    String(segundo)
      .toUpperCase()
      .includes('PRODU')
  ) {

    if (!produtoAtual) {
      continue;
    }

    const data =
      normalizarData(valores[3]);

    ordemAtual = {

      numeroSequencial:
        ordens.length + 1,

      tipoRegistro:
        'ORDEM_PRODUCAO',

      linhaOrigem:
        indice + 1,

      codigoProduto:
        produtoAtual.codigoProduto,

      produto:
        produtoAtual.produto,

      documento:
        valores[2] !== undefined
          ? String(valores[2])
          : null,

      dataEntrada:
        data?.iso || null,

      quantidadeProduzida:
        numero(valores[4]),

      unidade:
        valores[5]
          ? String(valores[5]).trim()
          : null,

      valorUnitario:
        numero(valores[6]),

      valorTotal:
        numero(valores[7]),

      materiaisUtilizados: []
    };

    ordens.push(ordemAtual);

    continue;
  }

  // ---------------------------------------------------
  // MATERIAL CONSUMIDO
  //
  // 2001 - MATERIAL A... QTD UN VALOR VALOR TOTAL
  // ---------------------------------------------------

  if (
    ordemAtual &&
    valores.length >= 5 &&
    primeiro !== undefined &&
    segundo !== undefined &&
    Number(primeiro) !== 1 &&
    String(segundo).trim().startsWith('-')
  ) {

    const codigoMaterial =
      Number(primeiro);

    if (
      Number.isFinite(codigoMaterial)
    ) {

      ordemAtual.materiaisUtilizados.push({

        codigoMaterial,

        material:
          limparDescricao(segundo),

        quantidade:
          numero(valores[2]),

        unidade:
          valores[3]
            ? String(valores[3]).trim()
            : null,

        valorUnitario:
          numero(valores[4]),

        valorTotal:
          numero(valores[5])
      });
    }
  }
}

// =====================================================
// QUANTIDADE DE MATERIAIS POR OP
// =====================================================

for (const ordem of ordens) {

  ordem.quantidadeMateriais =
    ordem.materiaisUtilizados.length;
}

// =====================================================
// AGREGAÇÃO POR PRODUTO
// =====================================================

const produtosMap = {};

for (const ordem of ordens) {

  const chave =
    String(ordem.codigoProduto);

  if (!produtosMap[chave]) {

    produtosMap[chave] = {

      codigoProduto:
        ordem.codigoProduto,

      produto:
        ordem.produto,

      totalUnidades: 0,

      totalOrdens: 0,

      valorTotal: 0
    };
  }

  produtosMap[chave].totalUnidades +=
    ordem.quantidadeProduzida;

  produtosMap[chave].totalOrdens++;

  produtosMap[chave].valorTotal +=
    ordem.valorTotal;
}

const produtos =
  Object.values(produtosMap);

// =====================================================
// RANKING DE PRODUTOS
// =====================================================

const rankingProdutos =
  [...produtos].sort(
    (a, b) =>
      b.totalUnidades -
      a.totalUnidades
  );

const maisProduzido =
  rankingProdutos[0] || null;

const menosProduzido =
  rankingProdutos.length
    ? rankingProdutos[
        rankingProdutos.length - 1
      ]
    : null;

// =====================================================
// PRODUÇÃO POR DIA
// =====================================================

const diasMap = {};

for (const ordem of ordens) {

  const data =
    ordem.dataEntrada;

  if (!data) continue;

  if (!diasMap[data]) {

    diasMap[data] = {

      data,

      totalOrdens: 0,

      totalUnidades: 0,

      valorTotal: 0
    };
  }

  diasMap[data].totalOrdens++;

  diasMap[data].totalUnidades +=
    ordem.quantidadeProduzida;

  diasMap[data].valorTotal +=
    ordem.valorTotal;
}

const producaoPorDia =
  Object.values(diasMap)
    .sort(
      (a, b) =>
        a.data.localeCompare(b.data)
    );

// =====================================================
// TOTAIS CALCULADOS
// =====================================================

const totalUnidades =
  ordens.reduce(
    (total, ordem) =>
      total +
      ordem.quantidadeProduzida,
    0
  );

const valorTotal =
  ordens.reduce(
    (total, ordem) =>
      total +
      ordem.valorTotal,
    0
  );

// =====================================================
// LOCALIZA TOTAL GERAL INFORMADO PELO ERP
// =====================================================

let totalUnidadesERP = null;
let valorTotalERP = null;

for (const valores of linhas) {

  const texto =
    valores.join(' ');

  if (
    !texto
      .toUpperCase()
      .includes('TOTAL GERAL')
  ) {
    continue;
  }

  // Ex:
  // Total Geral: 10.000,0000 50.000,0000

  const numerosBR =
    texto.match(
      /[\d.]+,\d{2,4}/g
    );

  if (
    numerosBR &&
    numerosBR.length >= 2
  ) {

    totalUnidadesERP =
      numero(numerosBR[0]);

    valorTotalERP =
      numero(numerosBR[1]);

    break;
  }

  // Caso o n8n já transforme
  // as células em números
  const numeros =
    valores
      .map(v => numero(v))
      .filter(v => v > 0);

  if (numeros.length >= 2) {

    totalUnidadesERP =
      numeros[numeros.length - 2];

    valorTotalERP =
      numeros[numeros.length - 1];
  }
}

// =====================================================
// VALIDAÇÃO
// =====================================================

const erros = [];
const alertas = [];

if (!ehRelatorioProducao) {

  erros.push(
    'O arquivo enviado não foi identificado como Relatório de Entrada de Produção.'
  );
}

if (ordens.length === 0) {

  erros.push(
    'Nenhuma ordem de produção válida foi encontrada no arquivo.'
  );
}

if (!mesFormulario) {

  erros.push(
    `Mês informado no formulário é inválido: ${form.MES}`
  );
}

if (
  !/^\d{4}$/.test(
    anoFormularioTexto
  )
) {

  erros.push(
    `Ano informado no formulário é inválido: ${form.ANO}`
  );
}

// =====================================================
// VALIDA MÊS / ANO DAS ORDENS
// =====================================================

if (
  mesFormulario &&
  /^\d{4}$/.test(
    anoFormularioTexto
  )
) {

  const competenciasErradas =
    new Set();

  for (const ordem of ordens) {

    if (!ordem.dataEntrada) {
      continue;
    }

    const data =
      normalizarData(
        ordem.dataEntrada
      );

    if (!data) continue;

    if (
      data.mes !== mesFormulario ||
      data.ano !== anoFormulario
    ) {

      competenciasErradas.add(
        `${String(data.mes).padStart(2, '0')}/${data.ano}`
      );
    }
  }

  if (
    competenciasErradas.size > 0
  ) {

    erros.push(
      `A competência informada (${mesFormularioTexto}/${anoFormulario}) não corresponde às datas encontradas no relatório.`
    );
  }
}

// =====================================================
// CONFERE TOTAL DO ERP
// =====================================================

if (
  totalUnidadesERP !== null
) {

  const diferencaUnidades =
    Math.abs(
      totalUnidades -
      totalUnidadesERP
    );

  if (diferencaUnidades > 0.01) {

    alertas.push(
      `O total de unidades calculado pelo parser (${totalUnidades}) não corresponde ao total informado pelo ERP (${totalUnidadesERP}).`
    );
  }
}

if (
  valorTotalERP !== null
) {

  const diferencaValor =
    Math.abs(
      valorTotal -
      valorTotalERP
    );

  if (diferencaValor > 0.05) {

    alertas.push(
      `O valor total calculado pelo parser (${valorTotal.toFixed(2)}) não corresponde ao total informado pelo ERP (${valorTotalERP.toFixed(2)}).`
    );
  }
}

if (
  ehRelatorioProducao &&
  (
    totalUnidadesERP === null ||
    valorTotalERP === null
  )
) {

  alertas.push(
    'Não foi possível localizar o Total Geral informado pelo ERP.'
  );
}

// =====================================================
// STATUS FINAL
// =====================================================

let status = 'OK';

if (erros.length > 0) {

  status = 'ERRO';

} else if (alertas.length > 0) {

  status = 'ALERTA';
}

const parserOk =
  status !== 'ERRO';

// =====================================================
// SAÍDA PADRONIZADA
// =====================================================

return [{
  json: {

    parserOk,
    status,

    modulo:
      'PRODUCAO',

    competencia: {

      mes:
        mesFormularioTexto,

      numeroMes:
        mesFormulario,

      ano:
        anoFormulario,

      primeiraProducao:
        producaoPorDia.length
          ? producaoPorDia[0].data
          : null,

      ultimaProducao:
        producaoPorDia.length
          ? producaoPorDia[
              producaoPorDia.length - 1
            ].data
          : null
    },

    validacao: {

      totalLinhasLidas:
        linhas.length,

      totalOrdensEncontradas:
        ordens.length,

      totalUnidadesERP,

      totalUnidadesCalculado:
        totalUnidades,

      valorTotalERP,

      valorTotalCalculado:
        valorTotal,

      diferencaUnidades:
        totalUnidadesERP !== null
          ? Math.abs(
              totalUnidades -
              totalUnidadesERP
            )
          : null,

      diferencaValor:
        valorTotalERP !== null
          ? Math.abs(
              valorTotal -
              valorTotalERP
            )
          : null,

      alertas,
      erros
    },

    resumo: {

      totalOrdens:
        ordens.length,

      totalProdutos:
        produtos.length,

      totalDiasProducao:
        producaoPorDia.length,

      totalUnidades,

      valorTotal,

      mediaPorOrdem:
        ordens.length
          ? totalUnidades /
            ordens.length
          : 0,

      maisProduzido,

      menosProduzido
    },

    ordens,

    produtos,

    producaoPorDia,

    rankingProdutos
  }
}];

const items = $input.all();

// =====================================================
// FUNÇÕES
// =====================================================

function numeroBR(valor) {
  if (valor === null || valor === undefined || valor === '') return 0;

  return Number(
    String(valor)
      .replace(/\./g, '')
      .replace(',', '.')
  );
}

// =====================================================
// TRANSFORMA TUDO QUE VEIO DO XLS EM LINHAS DE TEXTO
// =====================================================

const linhas = [];

for (const item of items) {
  for (const valor of Object.values(item.json || {})) {
    if (valor === null || valor === undefined) continue;

    const texto = String(valor).trim();

    if (texto) {
      linhas.push(texto);
    }
  }
}

// =====================================================
// IDENTIFICA O RELATÓRIO
// =====================================================

const ehRelatorioCompras = linhas.some(linha =>
  linha.toUpperCase().includes('RELATÓRIO DE COMPRAS SINTÉTICO') ||
  linha.toUpperCase().includes('RELATORIO DE COMPRAS SINTETICO')
);

// =====================================================
// DATA DE GERAÇÃO DO RELATÓRIO
// =====================================================

let dataGeracao = null;

for (const linha of linhas) {
  const match = linha.match(/Data:\s*(\d{2}\/\d{2}\/\d{4})/i);

  if (match) {
    dataGeracao = match[1];
    break;
  }
}

// =====================================================
// REGEX DAS COMPRAS
// =====================================================

const regexCompra =
  /^\s*(\S+)\s+-\s+(\d+)\s+(.+?)\s+([\d.]+,\d{2})\s+([\d.,]+)\s*$/;

const compras = [];

// =====================================================
// LÊ AS LINHAS
// =====================================================

for (const linha of linhas) {

  const match = linha.match(regexCompra);

  if (!match) continue;

  const [
    _,
    documento,
    codigoFornecedor,
    fornecedor,
    valorLiquido,
    percentual
  ] = match;

  compras.push({
    documento: documento.trim(),
    codigoFornecedor: codigoFornecedor.trim(),
    fornecedor: fornecedor.trim(),
    valorLiquido: numeroBR(valorLiquido),
    percentual: numeroBR(percentual)
  });
}

// =====================================================
// TOTAL INFORMADO PELO ERP
// =====================================================

let totalInformadoERP = null;

for (const linha of linhas) {

  const match = linha.match(
    /Total Compras\/Despesas\s+([\d.]+,\d{2})/i
  );

  if (match) {
    totalInformadoERP = numeroBR(match[1]);
    break;
  }
}

// =====================================================
// TOTAL CALCULADO
// =====================================================

const totalCalculado = compras.reduce(
  (total, compra) => total + compra.valorLiquido,
  0
);

// =====================================================
// AGRUPAMENTO POR FORNECEDOR
// =====================================================

const mapaFornecedores = {};

for (const compra of compras) {

  const chave = `${compra.codigoFornecedor}-${compra.fornecedor}`;

  if (!mapaFornecedores[chave]) {

    mapaFornecedores[chave] = {
      codigoFornecedor: compra.codigoFornecedor,
      fornecedor: compra.fornecedor,
      quantidadeCompras: 0,
      valorTotal: 0
    };
  }

  mapaFornecedores[chave].quantidadeCompras++;
  mapaFornecedores[chave].valorTotal += compra.valorLiquido;
}

const fornecedores = Object.values(mapaFornecedores)
  .sort((a, b) => b.valorTotal - a.valorTotal);

// =====================================================
// RANKINGS
// =====================================================

const comprasOrdenadas = [...compras]
  .sort((a, b) => b.valorLiquido - a.valorLiquido);

const maiorCompra =
  comprasOrdenadas.length > 0
    ? comprasOrdenadas[0]
    : null;

const menorCompra =
  comprasOrdenadas.length > 0
    ? comprasOrdenadas[comprasOrdenadas.length - 1]
    : null;

const maiorFornecedor =
  fornecedores.length > 0
    ? fornecedores[0]
    : null;

const menorFornecedor =
  fornecedores.length > 0
    ? fornecedores[fornecedores.length - 1]
    : null;

// =====================================================
// VALIDAÇÃO DO PARSER
// =====================================================

let status = 'OK';
let parserOk = true;
const alertas = [];
const erros = [];

if (!ehRelatorioCompras) {

  parserOk = false;
  status = 'ERRO';

  erros.push(
    'O arquivo enviado não foi identificado como Relatório de Compras Sintético.'
  );
}

if (compras.length === 0) {

  parserOk = false;
  status = 'ERRO';

  erros.push(
    'Nenhuma compra/despesa válida foi encontrada no arquivo.'
  );
}

// Confere se nossa soma bate com o ERP
if (
  parserOk &&
  totalInformadoERP !== null
) {

  const diferenca =
    Math.abs(totalCalculado - totalInformadoERP);

  if (diferenca > 0.02) {

    status = 'ALERTA';

    alertas.push(
      `O total calculado (${totalCalculado.toFixed(2)}) não corresponde ao total informado pelo ERP (${totalInformadoERP.toFixed(2)}).`
    );
  }
}

// =====================================================
// SAÍDA PADRONIZADA
// =====================================================

return [{
  json: {

    parserOk,
    status,

    modulo: 'COMPRAS',

    dataGeracao,

    validacao: {
      totalLinhasLidas: linhas.length,
      totalLancamentosEncontrados: compras.length,
      totalInformadoERP,
      totalCalculado,
      diferencaTotal:
        totalInformadoERP !== null
          ? Math.abs(totalCalculado - totalInformadoERP)
          : null,
      alertas,
      erros
    },

    resumo: {
      totalLancamentos: compras.length,
      totalFornecedores: fornecedores.length,
      totalGasto: totalCalculado,

      maiorCompra,
      menorCompra,

      maiorFornecedor,
      menorFornecedor
    },

    compras,

    fornecedores,

    rankingFornecedores: fornecedores.slice(0, 10)
  }
}];

const items = $input.all();
const form = $('Envio de Relatório ERP').first().json;

// =====================================================
// FUNÇÕES
// =====================================================

function numeroBR(valor) {
  if (typeof valor === 'number') return valor;

  if (valor === null || valor === undefined || valor === '') {
    return 0;
  }

  return Number(
    String(valor)
      .replace(/\./g, '')
      .replace(',', '.')
  );
}

function dataISO(dataBR) {
  const [dia, mes, ano] = dataBR.split('/');
  return `${ano}-${mes}-${dia}`;
}

function competenciaData(dataBR) {
  const [, mes, ano] = dataBR.split('/');

  return {
    mes: Number(mes),
    ano: Number(ano)
  };
}

const meses = {
  JANEIRO: 1,
  FEVEREIRO: 2,
  MARÇO: 3,
  ABRIL: 4,
  MAIO: 5,
  JUNHO: 6,
  JULHO: 7,
  AGOSTO: 8,
  SETEMBRO: 9,
  OUTUBRO: 10,
  NOVEMBRO: 11,
  DEZEMBRO: 12
};

// =====================================================
// DADOS DO FORMULÁRIO
// =====================================================

const mesFormularioTexto = String(form.MES || '')
  .trim()
  .toUpperCase();

const mesFormulario = meses[mesFormularioTexto];

const anoFormularioTexto = String(form.ANO || '').trim();
const anoFormulario = Number(anoFormularioTexto);

// =====================================================
// TRANSFORMA XLS EM LINHAS
// =====================================================

const linhas = [];

for (const item of items) {

  const valores = Object.values(item.json || {})
    .filter(valor =>
      valor !== null &&
      valor !== undefined &&
      String(valor).trim() !== ''
    );

  if (valores.length === 0) continue;

  linhas.push(
    valores.map(v => String(v)).join(' ').trim()
  );
}

// =====================================================
// IDENTIFICA O RELATÓRIO
// =====================================================

const ehRelatorioVendas = linhas.some(linha => {

  const texto = linha.toUpperCase();

  return (
    texto.includes('RELATÓRIO DE VENDAS') ||
    texto.includes('RELATORIO DE VENDAS')
  );
});

// =====================================================
// PERÍODO INFORMADO PELO ERP
// =====================================================

let dataInicial = null;
let dataFinal = null;

for (const linha of linhas) {

  const match = linha.match(
    /Relat[oó]rio de Vendas de\s+(\d{2}\/\d{2}\/\d{4})\s+[àa]\s+(\d{2}\/\d{2}\/\d{4})/i
  );

  if (match) {
    dataInicial = match[1];
    dataFinal = match[2];
    break;
  }
}

// =====================================================
// REGEX
// =====================================================

const numeroRegex = '-?[\\d.]+,\\d{2,4}';

const regexVenda = new RegExp(
  '^\\s*' +
  '(\\d{2}\\/\\d{2}\\/\\d{4})\\s+' + // Data
  '(\\d+)\\s+' +                     // Empresa
  '(\\S+)\\s+' +                     // Documento
  '(.+?)\\s+' +                      // Cliente
  `(${numeroRegex})\\s+` +           // Quantidade
  '([A-Za-z]+)\\s+' +                // Unidade
  `(${numeroRegex})\\s+` +           // Valor Unitário
  `(${numeroRegex})\\s+` +           // Desconto Comercial
  `(${numeroRegex})\\s+` +           // Desc/Acréscimo Financeiro
  `(${numeroRegex})\\s+` +           // Líquido
  `(${numeroRegex})\\s+` +           // ICMS
  `(${numeroRegex})\\s+` +           // IPI
  `(${numeroRegex})\\s+` +           // Outros
  `(${numeroRegex})` +               // TOTAL
  '\\s*\\+?\\s*$'
);

const regexProduto =
  /^\s*(\d+)\s+-\s+(.+?)\s*$/;

// =====================================================
// PARSER
// =====================================================

const produtosMap = {};
const vendas = [];

let produtoAtual = null;

for (const linha of linhas) {

  // ---------------------------------------------------
  // CABEÇALHO DO PRODUTO
  // Ex:
  // 1001 - PRODUCT A
  // ---------------------------------------------------

  const produtoMatch = linha.match(regexProduto);

  if (
    produtoMatch &&
    !linha.match(/^\d{2}\/\d{2}\/\d{4}/)
  ) {

    const codigoProduto = produtoMatch[1];
    const produto = produtoMatch[2].trim();

    if (!produtosMap[codigoProduto]) {
      produtosMap[codigoProduto] = {
        codigoProduto,
        produto,
        vendas: []
      };
    }

    produtoAtual = produtosMap[codigoProduto];

    continue;
  }

  // ---------------------------------------------------
  // LINHA DE VENDA
  // ---------------------------------------------------

  const vendaMatch = linha.match(regexVenda);

  if (!vendaMatch) continue;

  if (!produtoAtual) continue;

  const [
    _,
    data,
    empresa,
    documento,
    clienteCompleto,
    quantidade,
    unidade,
    valorUnitario,
    descontoComercial,
    ajusteFinanceiro,
    valorLiquido,
    icms,
    ipi,
    outrosValores,
    valorTotal
  ] = vendaMatch;

  // Cliente vem como:
  // 2001 - CUSTOMER EXAMPLE

  let codigoCliente = null;
  let cliente = clienteCompleto.trim();

  const clienteMatch =
    cliente.match(/^(\d+)\s*-\s*(.+)$/);

  if (clienteMatch) {
    codigoCliente = clienteMatch[1];
    cliente = clienteMatch[2].trim();
  }

  const venda = {
    data: dataISO(data),
    dataOriginal: data,

    empresa,
    documento,

    codigoCliente,
    cliente,

    codigoProduto: produtoAtual.codigoProduto,
    produto: produtoAtual.produto,

    quantidade: numeroBR(quantidade),
    unidade: unidade.trim(),

    valorUnitario: numeroBR(valorUnitario),

    descontoComercial:
      numeroBR(descontoComercial),

    ajusteFinanceiro:
      numeroBR(ajusteFinanceiro),

    valorLiquido:
      numeroBR(valorLiquido),

    icms:
      numeroBR(icms),

    ipi:
      numeroBR(ipi),

    outrosValores:
      numeroBR(outrosValores),

    valorTotal:
      numeroBR(valorTotal)
  };

  produtoAtual.vendas.push(venda);
  vendas.push(venda);
}

// =====================================================
// REMOVE PRODUTOS SEM VENDA
// =====================================================

const produtos = Object.values(produtosMap)
  .filter(produto => produto.vendas.length > 0);

// =====================================================
// TOTALIZA PRODUTOS
// =====================================================

for (const produto of produtos) {

  produto.totalUnidades =
    produto.vendas.reduce(
      (total, venda) =>
        total + venda.quantidade,
      0
    );

  produto.totalValor =
    produto.vendas.reduce(
      (total, venda) =>
        total + venda.valorTotal,
      0
    );

  produto.totalLiquido =
    produto.vendas.reduce(
      (total, venda) =>
        total + venda.valorLiquido,
      0
    );

  produto.quantidadeVendas =
    produto.vendas.length;
}

// =====================================================
// TOTAL GERAL CALCULADO
// =====================================================

const totalUnidades = vendas.reduce(
  (total, venda) => total + venda.quantidade,
  0
);

const totalValor = vendas.reduce(
  (total, venda) => total + venda.valorTotal,
  0
);

const totalLiquido = vendas.reduce(
  (total, venda) => total + venda.valorLiquido,
  0
);

// =====================================================
// TOTAL GERAL INFORMADO PELO ERP
// =====================================================

let totalInformadoERP = null;

for (const linha of linhas) {

  if (!/^\s*Vendas:/i.test(linha)) {
    continue;
  }

  const numeros =
    linha.match(/-?[\d.]+,\d{2,4}/g);

  // Linha final possui:
  // Bruto
  // Desconto Comercial
  // Desconto Financeiro
  // Líquido
  // ICMS
  // IPI
  // Outros
  // TOTAL
  // Preço Médio

  if (numeros && numeros.length >= 8) {
    totalInformadoERP =
      numeroBR(numeros[7]);
  }
}

// =====================================================
// CLIENTES
// =====================================================

const clientesUnicos = new Set();

for (const venda of vendas) {

  clientesUnicos.add(
    venda.codigoCliente ||
    venda.cliente
  );
}

// =====================================================
// PEDIDOS
// =====================================================

const pedidosMap = {};

for (const venda of vendas) {

  if (!pedidosMap[venda.documento]) {

    pedidosMap[venda.documento] = {
      documento: venda.documento,
      valorTotal: 0,
      quantidade: 0
    };
  }

  pedidosMap[venda.documento].valorTotal +=
    venda.valorTotal;

  pedidosMap[venda.documento].quantidade +=
    venda.quantidade;
}

const pedidos =
  Object.values(pedidosMap);

// =====================================================
// RANKINGS
// =====================================================

const rankingUnidades = [...produtos]
  .sort(
    (a, b) =>
      b.totalUnidades - a.totalUnidades
  );

const rankingValor = [...produtos]
  .sort(
    (a, b) =>
      b.totalValor - a.totalValor
  );

const maisVendidoUnidades =
  rankingUnidades[0] || null;

const menosVendidoUnidades =
  rankingUnidades.length
    ? rankingUnidades[rankingUnidades.length - 1]
    : null;

const maiorFaturamento =
  rankingValor[0] || null;

const menorFaturamento =
  rankingValor.length
    ? rankingValor[rankingValor.length - 1]
    : null;

// =====================================================
// VENDAS POR DIA
// =====================================================

const diasMap = {};

for (const venda of vendas) {

  if (!diasMap[venda.data]) {

    diasMap[venda.data] = {
      data: venda.data,
      quantidadeVendas: 0,
      totalUnidades: 0,
      totalValor: 0
    };
  }

  diasMap[venda.data].quantidadeVendas++;

  diasMap[venda.data].totalUnidades +=
    venda.quantidade;

  diasMap[venda.data].totalValor +=
    venda.valorTotal;
}

const vendasPorDia =
  Object.values(diasMap)
    .sort(
      (a, b) =>
        a.data.localeCompare(b.data)
    );

// =====================================================
// VALIDAÇÕES
// =====================================================

const erros = [];
const alertas = [];

if (!ehRelatorioVendas) {

  erros.push(
    'O arquivo enviado não foi identificado como Relatório de Vendas.'
  );
}

if (vendas.length === 0) {

  erros.push(
    'Nenhuma venda válida foi encontrada no arquivo.'
  );
}

if (!mesFormulario) {

  erros.push(
    `Mês informado no formulário é inválido: ${form.MES}`
  );
}

if (!/^\d{4}$/.test(anoFormularioTexto)) {

  erros.push(
    `Ano informado no formulário é inválido: ${form.ANO}`
  );
}

// =====================================================
// VALIDA TODAS AS DATAS DAS VENDAS
// =====================================================

if (
  mesFormulario &&
  /^\d{4}$/.test(anoFormularioTexto)
) {

  const competenciasDiferentes =
    new Set();

  for (const venda of vendas) {

    const competencia =
      competenciaData(venda.dataOriginal);

    if (
      competencia.mes !== mesFormulario ||
      competencia.ano !== anoFormulario
    ) {

      competenciasDiferentes.add(
        `${competencia.mes}/${competencia.ano}`
      );
    }
  }

  if (competenciasDiferentes.size > 0) {

    erros.push(
      `A competência informada (${form.MES}/${form.ANO}) não corresponde às datas encontradas no relatório.`
    );
  }
}

// =====================================================
// CONFERE TOTAL COM ERP
// =====================================================

if (totalInformadoERP !== null) {

  const diferenca =
    Math.abs(
      totalValor - totalInformadoERP
    );

  if (diferenca > 0.05) {

    alertas.push(
      `O total calculado pelo parser (${totalValor.toFixed(2)}) não corresponde ao total informado pelo ERP (${totalInformadoERP.toFixed(2)}).`
    );
  }

} else if (ehRelatorioVendas) {

  alertas.push(
    'Não foi possível localizar o Total Geral informado pelo ERP.'
  );
}

// =====================================================
// STATUS FINAL
// =====================================================

let status = 'OK';

if (erros.length > 0) {
  status = 'ERRO';
} else if (alertas.length > 0) {
  status = 'ALERTA';
}

const parserOk =
  status !== 'ERRO';

// =====================================================
// SAÍDA
// =====================================================

return [{
  json: {

    parserOk,
    status,

    modulo: 'VENDAS',

    competencia: {
      mes: mesFormularioTexto,
      numeroMes: mesFormulario,
      ano: anoFormulario,

      dataInicial,
      dataFinal
    },

    validacao: {
      totalLinhasLidas: linhas.length,
      totalVendasEncontradas: vendas.length,

      totalInformadoERP,
      totalCalculado: totalValor,

      diferencaTotal:
        totalInformadoERP !== null
          ? Math.abs(
              totalValor - totalInformadoERP
            )
          : null,

      alertas,
      erros
    },

    resumo: {
      totalProdutos: produtos.length,
      totalVendas: vendas.length,
      totalPedidos: pedidos.length,
      totalClientes: clientesUnicos.size,

      totalUnidades,
      totalLiquido,
      totalValor,

      ticketMedio:
        pedidos.length > 0
          ? totalValor / pedidos.length
          : 0,

      maisVendidoUnidades,
      menosVendidoUnidades,

      maiorFaturamento,
      menorFaturamento
    },

    produtos,
    vendas,
    vendasPorDia,

    rankingUnidades,
    rankingValor
  }
}];

